import Foundation

/// The Mac font metric table (docs/foundations-images-fonts.md block F1): what SwiftUI and CoreText measured on macOS for system fonts, text styles, mixed-script lines,
/// bundled-font synthesis and `Font.custom` name lookup. `FontMetricTableData.swift` is generated by `factory/tools/font-metrics/gen-table.py`; this loader only reads it.
/// Nothing in the runtime text path uses it yet (block F2 wires the Windows side to it).
public final class FontMetricTable: @unchecked Sendable {   // immutable after init
    /// One SwiftUI single-line `Text`: its frame height, the first and last baseline measured from the frame top, and the width of "Hamburgefonstiv" (all points).
    public struct Line: Equatable, Sendable {
        public let height: Double, firstBaseline: Double, lastBaseline: Double, width: Double
    }
    /// CoreText metrics of the same font (points).
    public struct CoreText: Equatable, Sendable {
        public let ascent: Double, descent: Double, leading: Double, capHeight: Double, xHeight: Double, unitsPerEm: Double
        public let face: String
    }

    public static let shared: FontMetricTable = FontMetricTable(json: FontMetricTableData.json)

    private let doc: [String: Any]
    init(json: String) { doc = (try? JSONSerialization.jsonObject(with: Data(json.utf8))) as? [String: Any] ?? [:] }

    public var tool: String { doc["tool"] as? String ?? "" }
    public var macOS: String { doc["macOS"] as? String ?? "" }
    public var macOSBuild: String { doc["macOSBuild"] as? String ?? "" }
    public var isLoaded: Bool { !doc.isEmpty }

    private static func key(_ n: Double) -> String { String(format: "%g", n) }
    private func lines(_ table: String) -> [String: [Double]] { doc[table] as? [String: [Double]] ?? [:] }
    private static func line(_ a: [Double]?) -> Line? { a.flatMap { $0.count == 4 ? Line(height: $0[0], firstBaseline: $0[1], lastBaseline: $0[2], width: $0[3]) : nil } }

    /// `Font.system(size:weight:design:)`; weight names ultraLight, thin, light, regular, medium, semibold, bold, heavy, black; designs default, monospaced, serif, rounded; scale 1 or 2.5.
    public func system(size: Double, weight: String = "regular", design: String = "default", scale: Double) -> Line? {
        Self.line(lines("swiftUISystem")["\(design)|\(weight)|\(Self.key(size))|\(Self.key(scale))"])
    }
    /// A text style (largeTitle, title, title2, title3, headline, subheadline, body, callout, footnote, caption, caption2) with `variant` default, a weight name, "bold()", "italic()" or "design-<design>".
    public func style(_ style: String, variant: String = "default", scale: Double) -> Line? {
        Self.line(lines("swiftUIStyles")["\(style)|\(variant)|\(Self.key(scale))"])
    }
    public func coreTextSystem(size: Double, weight: String = "regular", design: String = "default") -> CoreText? { coreText(doc["coreTextSystem"], "\(design)|\(weight)|\(Self.key(size))") }
    public func coreTextStyle(_ style: String, variant: String = "default") -> CoreText? { coreText(doc["coreTextStyles"], "\(style)|\(variant)") }
    private func coreText(_ t: Any?, _ k: String) -> CoreText? {
        guard let row = (t as? [String: [Any]])?[k], row.count == 7, let v = row.prefix(6).map({ ($0 as? NSNumber)?.doubleValue }) as? [Double],
              let fi = (row[6] as? NSNumber)?.intValue, let names = doc["faceNames"] as? [String], names.indices.contains(fi) else { return nil }
        return CoreText(ascent: v[0], descent: v[1], leading: v[2], capHeight: v[3], xHeight: v[4], unitsPerEm: v[5], face: names[fi])
    }
    /// Point size and PostScript name AppKit gives a text style (`NSFont.preferredFont(forTextStyle:)`).
    public func styleFont(_ style: String) -> (pointSize: Double, postScript: String)? {
        guard let e = (doc["coreTextStyleInfo"] as? [String: [String: Any]])?[style], let p = (e["pointSize"] as? NSNumber)?.doubleValue, let n = e["postScript"] as? String else { return nil }
        return (p, n)
    }
    /// A mixed-script line ("<font>|<line>", e.g. "system13|latin+ja") at a scale.
    public func mixedLine(_ key: String, scale: Double) -> Line? {
        Self.line(((doc["mixedScripts"] as? [String: Any])?[key] as? [String: Any])?["swiftUI@\(Self.key(scale))"] as? [Double])
    }
    /// The raw measured document, for facts that are not rows (synthesis, lookup).
    public var raw: [String: Any] { doc }
}
